options.getOption:
const getVal = (refId, fieldName) => {
  const s = context.panel.data.series.find(s => s.refId === refId);
  if (!s) return 0;
  const f = s.fields.find(f => f.name === fieldName);
  if (!f || !f.values || !f.values.length) return 0;
  return Number(f.values[f.values.length - 1]) || 0;
};

const fromMs    = Number(context.grafana.replaceVariables('$__from'));
const toMs      = Number(context.grafana.replaceVariables('$__to'));
const durationH = (toMs - fromMs) / 3_600_000;

const isLive = durationH < (6 / 60);   // < 6 min → current watts
const minVal = isLive ? 1 : durationH; // W cutoff (live) or Wh cutoff (energy, ≈1 Wh/h)

const fmtVal = (val) => {
  if (isLive)      return `${Math.round(val)} W`;
  if (val >= 1000) return `${(val / 1000).toFixed(2)} kWh`;
  return `${Math.round(val)} Wh`;
};

// Live: latest watts  |  Energy: kWh × 1000 → Wh  |  Battery energy: AVG W × durationH → Wh
const pv        = isLive ? Math.max(0, getVal('A',  'PV'))              : Math.max(0, getVal('AE', 'PV_kwh'))          * 1000;
const battEntl  = isLive ? Math.max(0, getVal('B',  'BattEntl'))        : Math.max(0, getVal('BE', 'BattEntl'))        * durationH;
const battLaden = isLive ? Math.max(0, getVal('B',  'BattLaden'))       : Math.max(0, getVal('BE', 'BattLaden'))       * durationH;
const netzbezug = isLive ? Math.max(0, getVal('C',  'Netzbezug'))       : Math.max(0, getVal('CI', 'Netzbezug_kwh'))   * 1000;
const netzeinsp = isLive ? Math.max(0, getVal('C',  'Netzeinspeisung')) : Math.max(0, getVal('CX', 'Netzeinspeis_kwh')) * 1000;
const haus      = isLive ? Math.max(0, getVal('D',  'Haus'))            : Math.max(0, getVal('DE', 'Haus_kwh'))        * 1000;

const COLORS = {
  'PV':                   '#F4D03F',
  'Batterie':             '#2ECC71',
  'Netzbezug':            '#E74C3C',
  'Netzeinspeisung':      '#F39C12',
  'Gesamt':               '#3498DB',
  'Haus':                 '#8E44AD',
  'Batterie laden':       '#27AE60',
  'Fernseher':            '#1ABC9C',
  'Geschirrspüler':       '#16A085',
  'Hauswasserversorgung': '#2980B9',
  'Herd':                 '#E67E22',
  'Kaffeemaschine':       '#D35400',
  'Kühlschrank':          '#8E44AD',
  'Lampe':                '#F39C12',
  'Trockner':             '#C0392B',
  'Waschmaschine':        '#7F8C8D',
  'Wärmepumpe':           '#1ABC9C',
  'Wärmepumpe ST':        '#16A085',
  'Zirkulationspumpe':    '#2C3E50',
  'Sonstiges':            '#95A5A6',
};

const DEPTH = {
  'PV': 0, 'Batterie': 0, 'Netzbezug': 0,
  'Gesamt': 1,
  'Batterie laden': 2, 'Netzeinspeisung': 2, 'Haus': 2,
};

const nodes = [];
const links = [];
const addNode = (name, depth) => {
  if (!nodes.find(n => n.name === name)) {
    const d = depth !== undefined ? depth : (DEPTH[name] !== undefined ? DEPTH[name] : 3);
    nodes.push({name, depth: d, itemStyle: {color: COLORS[name] || '#95A5A6'}});
  }
};

if (pv        > minVal) { addNode('PV');       addNode('Gesamt'); links.push({source:'PV',        target:'Gesamt', value:pv}); }
if (battEntl  > minVal) { addNode('Batterie');  addNode('Gesamt'); links.push({source:'Batterie',  target:'Gesamt', value:battEntl}); }
if (netzbezug > minVal) { addNode('Netzbezug'); addNode('Gesamt'); links.push({source:'Netzbezug', target:'Gesamt', value:netzbezug}); }

if (battLaden > minVal) { addNode('Gesamt'); addNode('Batterie laden');  links.push({source:'Gesamt', target:'Batterie laden',  value:battLaden}); }
if (netzeinsp > minVal) { addNode('Gesamt'); addNode('Netzeinspeisung'); links.push({source:'Gesamt', target:'Netzeinspeisung', value:netzeinsp}); }
if (haus      > minVal) { addNode('Gesamt'); addNode('Haus');            links.push({source:'Gesamt', target:'Haus',            value:haus}); }

const addShelly = (powerRefId, energyRefId, hausNode) => {
  const refId    = isLive ? powerRefId : energyRefId;
  const valField = isLive ? 'watt' : 'kwh';
  const scale    = isLive ? 1 : 1000; // watts (live) or kWh→Wh (energy)
  const ser = context.panel.data.series.find(s => s.refId === refId);
  let total = 0;
  if (ser) {
    const dF = ser.fields.find(f => f.name === 'device');
    const vF = ser.fields.find(f => f.name === valField);
    if (dF && vF) {
      for (let i = 0; i < dF.values.length; i++) {
        const name = dF.values[i];
        const val  = Math.max(0, Number(vF.values[i]) || 0) * scale;
        if (val > minVal) {
          addNode(hausNode); addNode(name, 3);
          links.push({source:hausNode, target:name, value:val});
          total += val;
        }
      }
    }
  }
  return total;
};

const totalShelly = addShelly('E', 'EE', 'Haus');
const sonstiges = Math.max(0, haus - totalShelly);
if (sonstiges > minVal) { addNode('Sonstiges', 3); links.push({source:'Haus', target:'Sonstiges', value:sonstiges}); }

const isDark = context.grafana.theme?.isDark !== false;
return {
  tooltip: {trigger:'item', formatter: p => `${p.name}<br/>${fmtVal(p.value)}`},
  series: [{
    type: 'sankey',
    emphasis: {focus:'adjacency'},
    data: nodes,
    links,
    label: {color: isDark ? '#fff' : '#333', formatter: p => `${p.name}\n${fmtVal(p.value)}`},
    lineStyle: {color:'gradient', opacity:0.4},
    nodeWidth: 20,
    nodeGap: 24,
  }]
};

